// Build a consolidated Markdown vulnerability report from npm-audit + Trivy JSON.
// Usage: node build-vuln-report.mjs <npm-audit.json> <trivy.json> > report.md
// Missing/empty/unparseable inputs degrade to an empty section (never throws).
import { readFileSync } from "node:fs";

const SEV_ORDER = ["critical", "high", "medium", "low"];
const RANK = { critical: 0, high: 1, medium: 2, low: 3 };

function readJson(path) {
  try {
    const raw = readFileSync(path, "utf8").trim();
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

// --- npm audit (v2 schema: .vulnerabilities map) ---
function parseNpm(data) {
  const out = [];
  if (!data || typeof data.vulnerabilities !== "object") return out;
  for (const [name, v] of Object.entries(data.vulnerabilities)) {
    // npm uses "moderate"; normalize to the shared "medium" bucket. "info" is ignored.
    let sev = String(v.severity || "").toLowerCase();
    if (sev === "moderate") sev = "medium";
    if (!RANK.hasOwnProperty(sev)) continue;
    const via = Array.isArray(v.via) ? v.via.find((x) => typeof x === "object") : null;
    out.push({
      pkg: name,
      severity: sev,
      title: via?.title || "vulnerable dependency",
      fixed: v.fixAvailable === false ? "no fix" : "fix available",
      url: via?.url || "",
    });
  }
  return out;
}

// --- Trivy fs (.Results[].Vulnerabilities[]) ---
function parseTrivy(data) {
  const out = [];
  const results = data?.Results;
  if (!Array.isArray(results)) return out;
  for (const r of results) {
    for (const v of r.Vulnerabilities || []) {
      const sev = String(v.Severity || "").toLowerCase();
      if (!RANK.hasOwnProperty(sev)) continue;
      out.push({
        pkg: v.PkgName,
        severity: sev,
        id: v.VulnerabilityID,
        installed: v.InstalledVersion,
        fixed: v.FixedVersion || "none",
        target: r.Target,
      });
    }
  }
  return out;
}

function tally(rows) {
  const t = { critical: 0, high: 0, medium: 0, low: 0 };
  for (const r of rows) t[r.severity]++;
  return t;
}

function bySeverity(rows) {
  return [...rows].sort((a, b) => RANK[a.severity] - RANK[b.severity]);
}

const npm = parseNpm(readJson(process.argv[2]));
const trivy = parseTrivy(readJson(process.argv[3]));
const nt = tally(npm);
const tt = tally(trivy);
const total =
  Object.values(nt).reduce((a, b) => a + b, 0) +
  Object.values(tt).reduce((a, b) => a + b, 0);

const today = new Date().toISOString().slice(0, 10);
const lines = [];
lines.push(`# 🔒 Vulnerability report — ${today}`);
lines.push("");
lines.push(
  "_Auto-generated by the Security Scan workflow (biweekly: 1st & 15th). " +
    "Fixes land via grouped Dependabot PRs (label `dependencies`)._"
);
lines.push("");
lines.push(`**Total findings: ${total}**`);
lines.push("");
lines.push("| Source | Critical | High | Medium | Low |");
lines.push("| --- | --- | --- | --- | --- |");
lines.push(`| npm (frontend) | ${nt.critical} | ${nt.high} | ${nt.medium} | ${nt.low} |`);
lines.push(`| Trivy (repo) | ${tt.critical} | ${tt.high} | ${tt.medium} | ${tt.low} |`);
lines.push("");

if (total === 0) {
  lines.push("✅ No known vulnerabilities detected.");
}

if (npm.length) {
  lines.push("## Frontend — npm audit");
  lines.push("");
  for (const v of bySeverity(npm)) {
    const link = v.url ? ` ([advisory](${v.url}))` : "";
    lines.push(`- **${v.pkg}** \`${v.severity}\` — ${v.title} · ${v.fixed}${link}`);
  }
  lines.push("");
}

if (trivy.length) {
  lines.push("## Repo — Trivy");
  lines.push("");
  for (const v of bySeverity(trivy)) {
    lines.push(
      `- **${v.pkg}** \`${v.severity}\` — ${v.id} · installed \`${v.installed}\`, fixed \`${v.fixed}\` · _${v.target}_`
    );
  }
  lines.push("");
}

// Machine-readable counts for downstream steps (Telegram summary).
const summary = SEV_ORDER.map(
  (s) => `${s[0].toUpperCase()}:${nt[s] + tt[s]}`
).join(" ");
lines.push(`<!-- VULN_SUMMARY ${summary} | TOTAL ${total} -->`);

process.stdout.write(lines.join("\n") + "\n");
